INSERT INTO public.attractions (id, name, description, image, distance, created_at) VALUES (1, 'Knossos Palace', 'The center of Minoan civilization and capital of Minoan Crete.', '/images/attractions/knossos.webp', '5.4 km', '2026-02-09 03:34:44.252047+00');
INSERT INTO public.attractions (id, name, description, image, distance, created_at) VALUES (2, 'Elafonisi Beach', 'Famous for its pink sand and turquoise waters.', '/images/attractions/elafonisi.webp', '120 km', '2026-02-09 03:34:44.252047+00');
INSERT INTO public.attractions (id, name, description, image, distance, created_at) VALUES (3, 'Heraklion Museum', 'Home to the most important collection of Minoan antiquities.', '/images/attractions/museum.webp', '0.5 km', '2026-02-09 03:34:44.252047+00');
INSERT INTO public.attractions (id, name, description, image, distance, created_at) VALUES (4, 'Psiloritis Mountain', 'The highest mountain in Crete, sacred to the goddess Rhea.', '/images/attractions/psiloritis.webp', '45 km', '2026-02-09 03:34:44.252047+00');
INSERT INTO public.attractions (id, name, description, image, distance, created_at) VALUES (5, 'Samaria Gorge', 'A World Biosphere Reserve and one of the longest gorges in Europe.', '/images/attractions/psiloritis.webp', '150 km', '2026-02-09 03:34:44.252047+00');
INSERT INTO public.attractions (id, name, description, image, distance, created_at) VALUES (6, 'Old Venetian Harbor', 'The iconic 14th-century harbor of Chania with its Egyptian lighthouse.', '/images/attractions/museum.webp', '140 km', '2026-02-09 03:34:44.252047+00');
