INSERT INTO public.faqs (id, question, answer, category, sort_order, created_at) VALUES (12, 'What is the check-in and check-out time?', 'Check-in is from 3:00 PM and check-out is until 11:00 AM. Early check-in or late check-out is subject to availability.', 'General', 0, '2026-02-09 05:10:45.102657+00');
INSERT INTO public.faqs (id, question, answer, category, sort_order, created_at) VALUES (13, 'Do you offer airport transfer?', 'Yes, we can arrange private transfer from Heraklion or Chania airport upon request (extra charge applies).', 'Services', 1, '2026-02-09 05:10:45.102657+00');
INSERT INTO public.faqs (id, question, answer, category, sort_order, created_at) VALUES (14, 'Is breakfast included?', 'no...', 'Dining', 2, '2026-02-09 05:10:45.102657+00');
INSERT INTO public.faqs (id, question, answer, category, sort_order, created_at) VALUES (15, 'Is the hotel suitable for children?', 'Kismet is designed for relaxation and tranquility. We welcome children over 12 years old.', 'General', 3, '2026-02-09 05:10:45.102657+00');
INSERT INTO public.faqs (id, question, answer, category, sort_order, created_at) VALUES (16, 'What is your cancellation policy?', 'Free cancellation up to 14 days before arrival. 50% charged if cancelled within 14 days.', 'Booking', 4, '2026-02-09 05:10:45.102657+00');
INSERT INTO public.faqs (id, question, answer, category, sort_order, created_at) VALUES (17, 'Are Pets Allowed?', 'Yes, we love pets!', 'Policies', 5, '2026-02-09 05:10:45.102657+00');
