INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000002', 'knossos', 'Knossos', 'A tribute to heritage, this room features textured stone walls and warm timber accents. The layout creates a cozy yet sophisticated retreat suitable for introspection and relaxation.', 60, 1, 2, 220.00, '{"Textured Stone Walls","Warm Ambient Lighting","Heritage Inspired Decor"}', '2026-02-09 03:34:44.252047+00', '2026-02-17 06:34:58.385521+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000004', 'olive-grove', 'Olive Grove', 'A grounded sanctuary on the garden level. Earthy tones and natural wood textures connect you directly to the hotel''s lush exterior spaces.', 50, 0, 2, 200.00, '{"Direct Garden Access","Private Patio","Earth Tone Palette"}', '2026-02-09 03:34:44.252047+00', '2026-02-17 06:34:58.517051+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000005', 'horizon', 'Horizon', 'Perched high for the best vantage point, Horizon is defined by its connection to the sky. Blue accents and airy fabrics mirror the view outside.', 70, 2, 3, 280.00, '{"Uninterrupted Sea Views","Top Floor Quietness","Breezy Atmosphere"}', '2026-02-09 03:34:44.252047+00', '2026-02-14 23:11:48.74778+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000001', 'aegean', 'Aegean Suite', 'Our signature suite, flooded with natural light from dual-aspect windows. The open-plan design connects a plush sleeping area with a private balcony overlooking the cretan seascape.', 60, 1, 3, 350.00, '{"Wrap-around Balcony","Corner Suite Privacy","Sun-drenched Interiors","Signature Welcome Amenity"}', '2026-02-09 03:34:44.252047+00', '2026-02-16 02:41:59.448091+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000003', 'meltemi', 'Meltemi', 'Designed for the modern traveler, Meltemi offers a crisp, minimalist aesthetic. White-washed walls and clean lines maximize the sense of space and airiness.', 45, 1, 2, 150.00, '{"Efficient Studio Layout","Crisp White Decor","Work-friendly Space"}', '2026-02-09 03:34:44.252047+00', '2026-02-17 06:34:58.185149+00', '05:00:00', '05:30:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000007', 'zephyr', 'Zephyr', 'Characterized by unique architectural arches and soft curves. This room breaks the mold of rectangular living with a fluid, organic layout.', 55, 1, 2, 190.00, '{"Unique Arched Architecture","Organic Flow","Romantic Ambiance"}', '2026-02-09 03:34:44.252047+00', '2026-02-13 02:47:06.143307+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000008', 'iris', 'Iris', 'Vibrant and centrally located, Iris brings the energy of the city inside. Large windows offer views of the bustling street life below, framed by soundproof glass.', 65, 1, 4, 240.00, '{"Urban Views","Spacious Living Room","Ideal for Families"}', '2026-02-09 03:34:44.252047+00', '2026-02-13 02:47:06.143307+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000009', 'poseidon', 'Poseidon', 'A true residence on the third floor. Poseidon features a distinct separation between the grand living space and the private quarters, perfect for entertaining or extended stays.', 90, 2, 5, 400.00, '{"Expansive Entertaining Space","Separate Living & Sleeping Wings","Private Jacuzzi"}', '2026-02-09 03:34:44.252047+00', '2026-02-13 02:47:06.143307+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000010', 'elysium', 'Elysium', 'The pinnacle of Kismet. Elysium is a sprawling penthouse suite offering multiple vantage points. From the multi-angle living room to the serene master bedroom, every corner renders a new perspective of luxury.', 110, 3, 2, 500.00, '{"360-Degree Views","Triple-Aspect Living Room","Exclusive Top Floor Privacy","Personal Concierge Service"}', '2026-02-09 03:34:44.252047+00', '2026-02-13 02:47:06.143307+00', '15:00:00', '11:00:00');
INSERT INTO public.rooms (id, slug, name, description, size_sqm, floor, max_occupancy, price_per_night, highlights, created_at, updated_at, check_in_time, check_out_time) VALUES ('00000000-0000-0000-0000-000000000006', 'selene', 'Selene', 'Named after the moon, this interior room focuses on quiet luxury. Soft grey tones and sound-absorbing textiles create a cocoon of silence.', 40, 0, 2, 200.00, '{"Ultimate Quiet","Sleep-Centric Design","Cool & Shaded"}', '2026-02-09 03:34:44.252047+00', '2026-02-13 04:08:04.652424+00', '15:00:00', '11:00:00');
